package com.dropai.generator;
import com.dropai.generator.blueprint.*;import com.dropai.generator.engine.*;import org.junit.jupiter.api.*;import java.nio.file.*;import static org.junit.jupiter.api.Assertions.*;
class SingleEntityCrudVerticalSliceTest{@Test void createsDeterministicProject()throws Exception{Path fixture=Path.of("..","docs","blueprints","library-crud.blueprint.json").normalize();BlueprintPipeline pipeline=new BlueprintPipeline();var model=pipeline.normalize(pipeline.parse(Files.readAllBytes(fixture)));assertEquals("book:view",model.permissions().get(0).code());assertEquals(14,model.filePlans().size());Path output=Files.createTempDirectory("dokiai-generator-test-");try(TemplateEngine engine=new TemplateEngine()){Path root=engine.generate(model,output);assertTrue(Files.exists(root.resolve("backend/src/main/java/com/dokiai/library/controller/BookController.java")));assertTrue(Files.exists(root.resolve("frontend/src/views/book/index.vue")));assertTrue(Files.exists(root.resolve("sql/database.sql")));assertTrue(Files.exists(root.resolve("manifest.json")));assertTrue(Files.exists(output.resolve("library-system.zip")));}finally{try(var paths=Files.walk(output)){for(Path p:paths.sorted(java.util.Comparator.reverseOrder()).toList())Files.deleteIfExists(p);}}}}
